Table schema:
```sql
CREATE TABLE IF NOT EXISTS tiktok_briefs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ia_identifier TEXT NOT NULL REFERENCES ia_content(identifier),
  topic_id TEXT NOT NULL,
  topic_name TEXT NOT NULL,
  source_url TEXT NOT NULL,
  source_title TEXT NOT NULL,
  hook TEXT NOT NULL,             -- first 3-second on-screen text
  caption TEXT NOT NULL,          -- full TikTok caption (under 2200 chars)
  hashtags TEXT[] NOT NULL,       -- 5-10 hashtags without #
  music_direction TEXT NOT NULL,  -- genre + mood + example track style
  duration_seconds INT NOT NULL,  -- recommended clip length (15-34)
  platform TEXT NOT NULL,         -- 'tiktok' | 'instagram_reels' | 'youtube_shorts'
  viral_trigger TEXT NOT NULL,    -- primary trigger from topic config
  score FLOAT NOT NULL,           -- copied from ia_content.score
  status TEXT NOT NULL DEFAULT 'draft',  -- draft | approved | posted | rejected
  generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  sprint_id TEXT NOT NULL,
  posted_at TIMESTAMPTZ,
  post_url TEXT
);

CREATE INDEX IF NOT EXISTS tiktok_briefs_status_idx ON tiktok_briefs (status, score DESC);
CREATE INDEX IF NOT EXISTS tiktok_briefs_topic_idx ON tiktok_briefs (topic_id);
```

