if (import.meta.url === `file://${process.argv[1]}`) {
  const isDryRun = process.argv.includes('--dry-run');
  const topicFilter = process.argv.find(a => a.startsWith('--topic='))?.split('=')[1];
  const config: BriefRunConfig = {
    limit: 20,
    min_score: 40,
    sprint_id: 'sprint-053',
    dry_run: isDryRun,
    topic_filter: topicFilter,
  };
  runBriefGenerator(config).then(r => {
    console.log(`\n=== BRIEFS COMPLETE ===`);
    console.log(`Generated: ${r.briefs_generated} | Stored: ${r.briefs_stored} | Errors: ${r.errors.length}`);
